"""Controlled test sets generated by this script (no third-party code):
 (a) circular dependencies and dependency edges with ground truth by construction (static analysis only);
 (b) potentially-unreferenced functions, ground truth = functions not executed when our generated main() runs."""
import sys, json, random, shutil, subprocess, logging
from pathlib import Path
EXP = Path(__file__).resolve().parent
sys.path.insert(0, str(EXP / "v1")); sys.path.insert(0, str(EXP / "v2"))
logging.disable(logging.CRITICAL)
import networkx as nx
from src.analyzer.repository_scanner import find_python_files as base_find
from src.analyzer.dependency_graph import build_dependency_graph as base_dep
from src.analyzer.call_graph import build_call_graph as base_cg
from src.analyzer.architecture_analysis import find_circular_dependencies as base_cycles
from src.analyzer.dead_code import find_potentially_unreferenced_functions as base_unref
from ca2 import engine as E2
import gen_heldout as G
PY = str(EXP / "venv/Scripts/python.exe")


def prf(tp, fp, fn):
    p = tp / (tp + fp) if tp + fp else 0.0; r = tp / (tp + fn) if tp + fn else 0.0
    return {"tp": tp, "fp": fp, "fn": fn, "P": round(p, 4), "R": round(r, 4), "F1": round(2 * p * r / (p + r), 4) if p + r else 0.0}


# ------------------------------------------------------------ (a) imports and cycles
STYLES = ["absolute", "from_submodule", "relative_name", "relative_module", "aliased", "in_function", "init_reexport"]


def gen_cycle_project(i, rng, root):
    pk = f"pkg{i}"
    d = root / f"c{i:03d}" / pk
    d.mkdir(parents=True)
    mods = [f"m{k}" for k in range(rng.randint(5, 9))]
    edges = set()
    for a in range(len(mods)):                      # acyclic backbone
        for b in range(a + 1, len(mods)):
            if rng.random() < 0.18:
                edges.add((mods[a], mods[b]))
    for _ in range(rng.choice([0, 1, 1, 2])):       # injected cycles
        cyc = rng.sample(mods, rng.randint(2, 3))
        for x, y in zip(cyc, cyc[1:] + cyc[:1]):
            edges.add((x, y))
    src = {m: [] for m in mods}
    init_lines = []
    truth = set()
    for a, b in sorted(edges):
        st = rng.choice(STYLES)
        if st == "absolute":
            src[a].append(f"import {pk}.{b}"); truth.add((f"{pk}.{a}", f"{pk}.{b}"))
        elif st == "from_submodule":
            src[a].append(f"from {pk} import {b}"); truth.add((f"{pk}.{a}", f"{pk}.{b}"))
        elif st == "relative_name":
            src[a].append(f"from .{b} import value_{b}"); truth.add((f"{pk}.{a}", f"{pk}.{b}"))
        elif st == "relative_module":
            src[a].append(f"from . import {b}"); truth.add((f"{pk}.{a}", f"{pk}.{b}"))
        elif st == "aliased":
            src[a].append(f"import {pk}.{b} as alias_{b}"); truth.add((f"{pk}.{a}", f"{pk}.{b}"))
        elif st == "in_function":
            src[a].append(f"def lazy_{b}():\n    from {pk} import {b}\n    return {b}"); truth.add((f"{pk}.{a}", f"{pk}.{b}"))
        else:  # the package __init__ re-exports b; module a imports the module directly
            init_lines.append(f"from .{b} import value_{b}"); truth.add((pk, f"{pk}.{b}"))
            src[a].append(f"from {pk}.{b} import value_{b}"); truth.add((f"{pk}.{a}", f"{pk}.{b}"))
    for m in mods:
        (d / f"{m}.py").write_text("\n".join(src[m] + [f"value_{m} = 1"]) + "\n")
    (d / "__init__.py").write_text("\n".join(sorted(set(init_lines))) + "\n")
    return d.parent, truth


def run_cycles(n=60):
    rng = random.Random(101)
    root = EXP / "synth_cycles"
    shutil.rmtree(root, ignore_errors=True); root.mkdir()
    agg = {k: {"edge": [0, 0, 0], "cycle": [0, 0, 0]} for k in ("baseline", "proposed")}
    n_cycles = n_edges = 0
    for i in range(n):
        proj, truth = gen_cycle_project(i, rng, root)
        g_t = nx.DiGraph(list(truth))
        t_c = {frozenset(c) for c in nx.strongly_connected_components(g_t) if len(c) > 1}
        n_cycles += len(t_c); n_edges += len(truth)
        r = proj.resolve()
        gb = base_dep(base_find(str(r)), r)
        gp = E2.build_dependency_graph(E2.Project(r), strict_from_imports=True)
        for key, g, cyc in (("baseline", gb, base_cycles(gb)), ("proposed", gp, [c for c in E2.find_cycles(gp) if len(c) > 1])):
            pe = set(g.edges); pc = {frozenset(c) for c in cyc}
            for lab, pred, tr in (("edge", pe, truth), ("cycle", pc, t_c)):
                a = agg[key][lab]; a[0] += len(pred & tr); a[1] += len(pred - tr); a[2] += len(tr - pred)
    return {"projects": n, "truth_edges": n_edges, "truth_cycles": n_cycles,
            "results": {k: {lab: prf(*v) for lab, v in d.items()} for k, d in agg.items()}}


# ------------------------------------------------------------ (b) unreferenced functions
DEAD = ['''def legacy_{k}(x):
    return x + 1

def old_helper_{k}(x):
    return legacy_{k}(x)

class Unused{k}:
    def never_{k}(self):
        return 0
''']
TRAP = '''HOOKS_{k} = {{}}

def hook_{k}(x):
    return x

def call_by_name_{k}(name, x):
    return globals()[name](x)
'''


def run_dead(n=40):
    rng = random.Random(202)
    root = EXP / "synth_dead"
    shutil.rmtree(root, ignore_errors=True); (root / "dead").mkdir(parents=True)
    agg = {"baseline": [0, 0, 0], "proposed": [0, 0, 0]}
    total_dead = total_funcs = 0
    for i in range(n):
        pats = rng.sample(G.PATTERNS, rng.randint(2, 3))
        d = root / "dead" / f"proj{i:02d}"; d.mkdir()
        mains = []
        for j, p in enumerate(pats):
            files, m = p(f"{i}{j}")
            for fn, s in files.items():
                (d / fn).parent.mkdir(parents=True, exist_ok=True); (d / fn).write_text(s)
            mains.append(m)
        (d / f"extra{i}.py").write_text(DEAD[0].format(k=i) + "\n" + TRAP.format(k=i))
        mains.append(f"import extra{i}\nextra{i}.call_by_name_{i}('hook_{i}', 1)\n")
        body = "".join(mains)
        imports = "".join(l + "\n" for l in body.splitlines() if l.startswith(("import ", "from ")))
        rest = [l for l in body.splitlines() if not l.startswith(("import ", "from "))]
        (d / "main.py").write_text(imports + "\ndef main():\n" + "".join("    " + l + "\n" for l in rest) + "\nmain()\n")
        r = subprocess.run([PY, "-I", str(EXP / "_tracer.py"), str(d)], capture_output=True, text=True, timeout=60)
        if r.returncode != 0:
            raise RuntimeError(r.stderr[-300:])
        gt = json.loads((d / "callgraph.json").read_text())
        executed = {t for vs in gt.values() for t in vs}
        root_d = d.resolve()
        files = [f for f in root_d.rglob("*.py")]
        bg = base_cg(files, root_d)
        pg = E2.function_view(E2.build_call_graph(E2.Project(root_d))) if hasattr(E2, "function_view") else None
        if pg is None:
            full = E2.build_call_graph(E2.Project(root_d))
            pg = full.subgraph([x for x, a in full.nodes(data=True) if a.get("kind") == "function"]).copy()
        funcs = set(pg.nodes)
        dead = {f for f in funcs if f not in executed and f != "main.main"}
        total_dead += len(dead); total_funcs += len(funcs)
        # baseline names functions module.name: compare on (module, simple name)
        norm = lambda f: (f.split(".")[0] if not f.startswith("util") else ".".join(f.split(".")[:2]), f.split(".")[-1])
        t = {norm(f) for f in dead}
        for key, g in (("baseline", bg), ("proposed", pg)):
            pred = {norm(x["function"]) for x in base_unref(g, {"main.main"})}
            a = agg[key]; a[0] += len(pred & t); a[1] += len(pred - t); a[2] += len(t - pred)
    return {"projects": n, "functions": total_funcs, "never_executed": total_dead, "results": {k: prf(*v) for k, v in agg.items()}}


if __name__ == "__main__":
    out = {"cycles": run_cycles(), "dead": run_dead()}
    json.dump(out, open(EXP / "synth_results.json", "w"), indent=1)
    print(json.dumps(out, indent=1))
